function firstLoose(items: any[]): any {
  return items[0];
}

function first<T>(items: T[]): T | undefined {
  return items[0];
}

const loose = firstLoose([1, 2, 3]);
const num = first([1, 2, 3]);
const str = first(["a", "b"]);
const explicit = first<boolean>([]);

console.log(loose, num, str, explicit);
console.log(num.toFixed(1));

function longest<T extends { length: number }>(a: T, b: T): T {
  return a.length >= b.length ? a : b;
}

console.log(longest("apple", "fig"));
console.log(longest([1, 2], [3]));

longest(10, 20);

function pluck<T, K extends keyof T>(source: T, key: K): T[K] {
  return source[key];
}

const user = { id: 1, name: "Ada", admin: true };

const name = pluck(user, "name");
const admin = pluck(user, "admin");
console.log(name.toUpperCase(), admin);

pluck(user, "email");

interface ApiResponse<T> {
  ok: boolean;
  data: T;
}

class Stack<T> {
  private items: T[] = [];

  push(item: T): void {
    this.items.push(item);
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  get size(): number {
    return this.items.length;
  }
}

const stack = new Stack<number>();
stack.push(1);
stack.push(2);
console.log(stack.pop(), stack.size);

const response: ApiResponse<string[]> = { ok: true, data: ["a", "b"] };
console.log(response.data.length);

stack.push("three");
